    SELECT id INTO cat_id FROM analytics_categories WHERE name = r.cat_name LIMIT 1;
    INSERT INTO analytics_products (stock_code, name, category_id, sub_category_id, sub_category, pack_size)
    VALUES (r.stock_code, r.name, cat_id, NULL, r.sub_category, r.pack_size)
    ON CONFLICT (stock_code) DO UPDATE SET
      name = EXCLUDED.name,
      category_id = COALESCE(EXCLUDED.category_id, analytics_products.category_id),
      sub_category_id = COALESCE(EXCLUDED.sub_category_id, analytics_products.sub_category_id),
      pack_size = COALESCE(EXCLUDED.pack_size, analytics_products.pack_size);
